import { createContext } from 'react'

import { RegisterDialogTitle } from '../../hooks/useDialogTitle'

export interface DrawerContextProps {
  /**
   * Requests the drawer be closed — fires `onClose`. Wire this to any element's `onClick`; see
   * `useDrawer`.
   */
  close: () => void
  /**
   * Id generated by `Drawer` and applied automatically by `DrawerTitle` to itself, so the
   * dialog's `aria-labelledby` resolves to it without any manual wiring.
   */
  titleId?: string
}

export const DrawerContext = createContext<DrawerContextProps>({ close: () => {} })

// How a rendered `DrawerTitle` tells its `Drawer` the id it has (`useDialogTitle`). Apart from
// `DrawerContext`, whose value `useDrawer` returns to callers.
export const DrawerTitleContext = createContext<RegisterDialogTitle>(() => () => {})
